j:jelly.script:
$j('#${jvar_id}_list .icon-info').attr('onclick', $j('#${jvar_id}_list .icon-info').attr('onmouseover'));
$j('#${jvar_id}_list .icon-info').attr('onmouseover','');
$j('#${jvar_id}_list .icon-info').attr('onmouseout','');

$j('#${jvar_id}').attr('onchange',$j('#${jvar_id}').attr('onchange')+' ${jvar_id}Entered();');

$j('#${jvar_id}_list .form-control').removeAttr('title');

$j('#${jvar_id}_list .icon-info').attr('title','${gs.getMessage("Preview this record")}');

gel('sys_display.${jvar_id}').setAttribute('aria-required',true);

function ${jvar_id}Entered(){
	var element = document.getElementById('${jvar_id}');
	var labelDiv = element.parentElement.parentElement.childNodes[0];
	if(element.value){
		labelDiv.className += " is-filled";
	}
	setTimeout(function(){
		if(document.getElementById('${jvar_id}').value==="")
			labelDiv.className = "col-xs-4 col-md-2 text-right";
	},100);
}
